name: Infra Auto Remediation

on:
  workflow_dispatch:
  repository_dispatch:
    types: [infra-alert]

jobs:
  rate-limit:
    runs-on: ubuntu-latest
    outputs:
      skip: ${{ steps.check.outputs.skip }}
      needs-human: ${{ steps.check.outputs.needs-human }}
    steps:
      - name: Check rate limits
        id: check
        uses: actions/github-script@v6
        with:
          script: |
            const now = new Date();
            const fiveMinAgo = new Date(now.getTime() - 5 * 60 * 1000);
            const oneHourAgo = new Date(now.getTime() - 60 * 60 * 1000);
            const { data: runs } = await github.rest.actions.listWorkflowRuns({
              owner: context.repo.owner,
              repo: context.repo.repo,
              workflow_id: context.workflow,
              status: 'completed',
              per_page: 100
            });
            const recentRuns = runs.workflow_runs.filter(r => new Date(r.created_at) > fiveMinAgo);
            const hourlyRuns = runs.workflow_runs.filter(r => new Date(r.created_at) > oneHourAgo);
            const skip = recentRuns.length > 0;
            const needsHuman = hourlyRuns.length >= 10;
            core.setOutput('skip', skip);
            core.setOutput('needs-human', needsHuman);
      - name: Create needs-human issue
        if: steps.check.outputs.needs-human == 'true'
        uses: actions/github-script@v6
        with:
          script: |
            const title = 'Infra Auto Remediation needs human intervention';
            const body = 'Repeated alerts detected. Please investigate manually.';
            await github.rest.issues.create({
              owner: context.repo.owner,
              repo: context.repo.repo,
              title,
              body
            });

  remediation:
    needs: rate-limit
    if: needs.rate-limit.outputs.skip != 'true' && needs.rate-limit.outputs.needs-human != 'true'
    runs-on: ubuntu-latest
    steps:
      - name: Checkout repository
        uses: actions/checkout@v4
      - name: Run remediation script
        run: |
          echo "Running auto-remediation..."
          # Placeholder for actual remediation logic
          echo "Remediation completed."
      - name: Post findings to Discord
        if: env.DISCORD_WEBHOOK_URL
        env:
          DISCORD_WEBHOOK_URL: ${{ secrets.DISCORD_WEBHOOK_URL }}
        run: |
          curl -H "Content-Type: application/json" -X POST -d '{"content":"Auto-remediation completed successfully."}' $DISCORD_WEBHOOK_URL
      - name: Create GitHub issue
        uses: actions/github-script@v6
        with:
          script: |
            const title = 'Auto-remediation executed';
            const body = 'Auto-remediation was executed successfully.';
            await github.rest.issues.create({
              owner: context.repo.owner,
              repo: context.repo.repo,
              title,
              body
            });
